'use client';
import { useCallback, useEffect, useId, useMemo, useRef, useState } from 'react';
import { scaleLinear } from 'd3';
import { Breakdown, type Row } from './Breakdown';
import { RangeBrush } from './RangeBrush';
import { SCATTER_M, Scatter, type Mark } from './Scatter';
import {
  ALT, DEFAULT_STATE, PROCESSES, SCORE, SEED, VARIETIES, buildDataset, decodeState, encodeState, fmt, mean, pearson, summarise,
  type CompareDim, type Lot, type SortKey, type ViewState,
} from './data';
import s from './styles.module.css';

const DATA = buildDataset();
const LOT_IDS = new Set(DATA.lots.map((l) => l.id));
const REGIONS = [...DATA.nodes.values()].filter((n) => n.level === 'region');
const nodeName = (id: string) => DATA.nodes.get(id)?.name ?? id;
const PROC_LABEL = Object.fromEntries(PROCESSES.map((p) => [p.id, p.label])) as Record<string, string>;
const VAR_LABEL = Object.fromEntries(VARIETIES.map((v) => [v.id, v.label])) as Record<string, string>;
const DIM_OPTIONS: Record<CompareDim, readonly { id: string; label: string }[]> = {
  process: PROCESSES, variety: VARIETIES, region: REGIONS.map((r) => ({ id: r.id, label: r.name })),
};
const dimValue = (l: Lot, d: CompareDim) => (d === 'process' ? l.process : d === 'variety' ? l.variety : l.region);
const optLabel = (d: CompareDim, id: string) => DIM_OPTIONS[d].find((o) => o.id === id)?.label ?? id;
const BIN = 0.5;
const NBINS = Math.round((SCORE[1] - SCORE[0]) / BIN);
const binOf = (v: number) => Math.min(NBINS - 1, Math.max(0, Math.floor((v - SCORE[0]) / BIN)));
const describe = (l: Lot) => `${nodeName(l.farm)}, ${nodeName(l.region)}; ${fmt.int.format(l.altitude)} m; ${fmt.score(l.score)} points; ${PROC_LABEL[l.process]} ${VAR_LABEL[l.variety]}`;
const COLS: readonly { key: SortKey; label: string; num?: boolean }[] = [
  { key: 'id', label: 'Lot' }, { key: 'farm', label: 'Farm' }, { key: 'altitude', label: 'Altitude (m)', num: true },
  { key: 'score', label: 'Score (pts)', num: true }, { key: 'yield', label: 'Yield (kg/ha)', num: true },
  { key: 'process', label: 'Process' }, { key: 'variety', label: 'Variety' },
];
const H_MARGIN = { left: 40, right: 10 };

export default function DataExploration() {
  const uid = useId();
  const [st, setSt] = useState<ViewState>(DEFAULT_STATE);
  const [showBins, setShowBins] = useState(false);
  const [announce, setAnnounce] = useState('');
  const hydrated = useRef(false);
  const update = useCallback((patch: Partial<ViewState>) => setSt((x) => ({ ...x, ...patch })), []);

  // URL-hash state: read on mount and on hashchange; written back with replaceState (no history spam).
  useEffect(() => {
    const read = () => setSt(decodeState(window.location.hash, DATA.nodes, LOT_IDS));
    read();
    hydrated.current = true;
    window.addEventListener('hashchange', read);
    return () => window.removeEventListener('hashchange', read);
  }, []);
  useEffect(() => {
    if (!hydrated.current) return;
    const id = window.setTimeout(() => {
      const h = encodeState(st);
      if (window.location.hash.replace(/^#/, '') !== h) window.history.replaceState(window.history.state, '', h ? `#${h}` : window.location.pathname + window.location.search);
    }, 150);
    return () => window.clearTimeout(id);
  }, [st]);

  const level = st.path.length;
  const inPath = useCallback((l: Lot) => st.path.every((id, i) => (i === 0 ? l.region : i === 1 ? l.coop : l.farm) === id), [st.path]);
  const universe = useMemo(() => DATA.lots.filter((l) => st.proc.includes(l.process) && st.vari.includes(l.variety) && inPath(l)), [st.proc, st.vari, inPath]);
  const inSel = useCallback((l: Lot) => (!st.alt || (l.altitude >= st.alt[0] && l.altitude <= st.alt[1])) && (!st.score || (l.score >= st.score[0] && l.score <= st.score[1])), [st.alt, st.score]);
  const selected = useMemo(() => universe.filter(inSel), [universe, inSel]);
  const markOf = useCallback((l: Lot): Mark | null => {
    if (!st.cmp) return l.process;
    const v = dimValue(l, st.cmp.dim);
    return v === st.cmp.a ? 'a' : v === st.cmp.b ? 'b' : null;
  }, [st.cmp]);
  const groupA = useMemo(() => (st.cmp ? selected.filter((l) => markOf(l) === 'a') : []), [selected, markOf, st.cmp]);
  const groupB = useMemo(() => (st.cmp ? selected.filter((l) => markOf(l) === 'b') : []), [selected, markOf, st.cmp]);
  const sum = useMemo(() => summarise(selected), [selected]);
  const trend = useMemo(() => {
    if (selected.length < 5) return null;
    const xs = selected.map((l) => l.altitude), ys = selected.map((l) => l.score);
    const mx = mean(xs), my = mean(ys);
    let sxy = 0, sxx = 0;
    for (let i = 0; i < xs.length; i++) { sxy += (xs[i] - mx) * (ys[i] - my); sxx += (xs[i] - mx) ** 2; }
    if (!sxx) return null;
    const slope = sxy / sxx;
    return { slope, intercept: my - slope * mx, r: pearson(xs, ys), x0: Math.min(...xs), x1: Math.max(...xs) };
  }, [selected]);

  // Facet counts ignore their own facet, so an unchecked option still shows what it would add.
  const procCount = (p: string) => DATA.lots.filter((l) => l.process === p && st.vari.includes(l.variety) && inPath(l)).length;
  const varCount = (v: string) => DATA.lots.filter((l) => l.variety === v && st.proc.includes(l.process) && inPath(l)).length;
  const toggle = (key: 'proc' | 'vari', id: string) => setSt((x) => {
    const cur = x[key] as string[];
    const next = cur.includes(id) ? cur.filter((c) => c !== id) : [...cur, id];
    return next.length ? { ...x, [key]: next } : x;
  });

  // Drill-down rows: the children of the current node, or the lots of a farm at the leaf.
  const leaf = level === 3;
  const rows: Row[] = useMemo(() => {
    if (leaf) {
      return selected.map((l) => ({
        id: l.id, name: `${l.id} · ${PROC_LABEL[l.process]}`, n: 1, mean: l.score, p10: l.score, p90: l.score,
        a: markOf(l) === 'a' ? l.score : NaN, b: markOf(l) === 'b' ? l.score : NaN, drill: false, pinned: st.pin === l.id,
      }));
    }
    const parent = level ? st.path[level - 1] : null;
    const field = level === 0 ? 'region' : level === 1 ? 'coop' : 'farm';
    return [...DATA.nodes.values()].filter((n) => n.parent === parent && n.level === field).map((n) => {
      const ls = selected.filter((l) => l[field] === n.id);
      const sm = summarise(ls);
      const ga = ls.filter((l) => markOf(l) === 'a'), gb = ls.filter((l) => markOf(l) === 'b');
      return { id: n.id, name: n.name, n: sm.n, mean: sm.mean, p10: sm.p10, p90: sm.p90, a: ga.length >= 2 ? mean(ga.map((l) => l.score)) : NaN, b: gb.length >= 2 ? mean(gb.map((l) => l.score)) : NaN, drill: true };
    });
  }, [selected, level, leaf, st.path, st.pin, markOf]);
  const childNoun = level === 0 ? 'region' : level === 1 ? 'cooperative' : level === 2 ? 'farm' : 'lot';

  const bins = useMemo(() => {
    const b = Array.from({ length: NBINS }, (_, i) => ({ lo: SCORE[0] + i * BIN, all: 0, sel: 0, a: 0, b: 0 }));
    for (const l of universe) b[binOf(l.score)].all++;
    for (const l of selected) b[binOf(l.score)].sel++;
    for (const l of groupA) b[binOf(l.score)].a++;
    for (const l of groupB) b[binOf(l.score)].b++;
    return b;
  }, [universe, selected, groupA, groupB]);
  const altBins = useMemo(() => {
    const b = Array.from({ length: 14 }, (_, i) => ({ lo: ALT[0] + i * 100, n: 0 }));
    for (const l of universe) b[Math.min(13, Math.floor((l.altitude - ALT[0]) / 100))].n++;
    return b;
  }, [universe]);

  const sorted = useMemo(() => {
    const k = st.sort.key;
    const val = (l: Lot): string | number => (k === 'farm' ? nodeName(l.farm) : l[k]);
    return [...selected].sort((p, q) => {
      const a = val(p), b = val(q);
      return (typeof a === 'number' && typeof b === 'number' ? a - b : String(a).localeCompare(String(b))) * st.sort.dir || p.id.localeCompare(q.id);
    });
  }, [selected, st.sort]);
  const sortBy = (key: SortKey) => update({ sort: st.sort.key === key ? { key, dir: st.sort.dir === 1 ? -1 : 1 } : { key, dir: key === 'score' || key === 'altitude' || key === 'yield' ? -1 : 1 } });

  const pinned = st.pin ? DATA.lots.find((l) => l.id === st.pin) ?? null : null;
  const filtersText = [
    st.proc.length < PROCESSES.length ? st.proc.map((p) => PROC_LABEL[p]).join(' + ') : null,
    st.vari.length < VARIETIES.length ? st.vari.map((v) => VAR_LABEL[v]).join(' + ') : null,
    st.alt ? `${fmt.int.format(st.alt[0])}–${fmt.int.format(st.alt[1])} m` : null,
    st.score ? `${fmt.score(st.score[0])}–${fmt.score(st.score[1])} pts` : null,
  ].filter(Boolean).join(' · ');
  const where = level ? st.path.map(nodeName).join(' › ') : 'all four regions';
  const headline = `${selected.length} of ${universe.length} lots in ${where}${filtersText ? ` (${filtersText})` : ''}.`;
  const sA = summarise(groupA), sB = summarise(groupB);
  const summary = selected.length === 0
    ? `${headline} Nothing matches — widen a range or tick another option.`
    : st.cmp
      ? `${headline} ${optLabel(st.cmp.dim, st.cmp.a)}: ${sA.n} lots, mean ${fmt.mean(sA.mean)}. ${optLabel(st.cmp.dim, st.cmp.b)}: ${sB.n} lots, mean ${fmt.mean(sB.mean)}.${sA.n && sB.n ? ` Difference ${fmt.signed1.format(sA.mean - sB.mean)} points.` : ''}`
      : `${headline} Mean cup score ${fmt.mean(sum.mean)} (10th–90th percentile ${fmt.mean(sum.p10)}–${fmt.mean(sum.p90)}); ${fmt.pct.format(sum.share86)} score 86 or more.${trend && Number.isFinite(trend.r) ? ` Altitude and score are ${Math.abs(trend.r) >= 0.5 ? 'strongly' : Math.abs(trend.r) >= 0.3 ? 'moderately' : 'weakly'} associated here (r = ${fmt.r.format(trend.r)}) — an association in sample data, not a cause.` : ''}`;

  useEffect(() => {
    if (!hydrated.current) return;
    const id = window.setTimeout(() => setAnnounce(headline), 900);
    return () => window.clearTimeout(id);
  }, [headline]);

  const setCompare = (dim: CompareDim | 'off') => update({ cmp: dim === 'off' ? null : { dim, a: DIM_OPTIONS[dim][0].id, b: DIM_OPTIONS[dim][1].id } });
  const maxBin = Math.max(st.cmp ? 0.05 : 1, ...bins.map((b) => (st.cmp ? Math.max(b.a / Math.max(1, groupA.length), b.b / Math.max(1, groupB.length)) : b.all)));

  return (
    <div className={s.root} data-compare={st.cmp ? '' : undefined}>
      <div className={s.wrap}>
        <header className={s.head}>
          <p className={s.kicker}>Four Valleys Cupping Table · fictional quality programme <span className={s.sample}>Sample data</span></p>
          <h2 className={s.title}>Which lots cup best, <em>and what do they share?</em></h2>
          <p className={s.lede}>{DATA.lots.length} sample lots from four invented growing regions, scored on a 100-point cupping form. Filter, brush and drill down — every view, the table and the address bar stay in step, so a view can be shared by copying the link.</p>
        </header>

        <section className={s.toolbar} aria-label="Filters and comparison">
          <fieldset className={s.facet}>
            <legend>Process</legend>
            {PROCESSES.map((p) => (
              <label key={p.id} className={s.chip}>
                <input type="checkbox" checked={st.proc.includes(p.id)} onChange={() => toggle('proc', p.id)} disabled={st.proc.length === 1 && st.proc.includes(p.id)} />
                <span><span className={s.swatch} data-mark={p.id} aria-hidden="true" />{p.label}<span className={s.chipN}>{procCount(p.id)}</span></span>
              </label>
            ))}
          </fieldset>
          <fieldset className={s.facet}>
            <legend>Variety</legend>
            {VARIETIES.map((v) => (
              <label key={v.id} className={s.chip}>
                <input type="checkbox" checked={st.vari.includes(v.id)} onChange={() => toggle('vari', v.id)} disabled={st.vari.length === 1 && st.vari.includes(v.id)} />
                <span>{v.label}<span className={s.chipN}>{varCount(v.id)}</span></span>
              </label>
            ))}
          </fieldset>
          <div className={s.compare}>
            <label className={s.selectLabel}>
              <span>Compare</span>
              <select value={st.cmp?.dim ?? 'off'} onChange={(e) => setCompare(e.target.value as CompareDim | 'off')}>
                <option value="off">Off</option><option value="process">Process</option><option value="variety">Variety</option><option value="region">Region</option>
              </select>
            </label>
            {st.cmp ? (
              <>
                {(['a', 'b'] as const).map((g) => (
                  <label key={g} className={s.selectLabel}>
                    <span><span className={s.groupKey} data-g={g} aria-hidden="true" />{g === 'a' ? 'A' : 'B'}</span>
                    <select value={st.cmp![g]} onChange={(e) => update({ cmp: { ...st.cmp!, [g]: e.target.value } })}>
                      {DIM_OPTIONS[st.cmp!.dim].map((o) => <option key={o.id} value={o.id} disabled={o.id === st.cmp![g === 'a' ? 'b' : 'a']}>{o.label}</option>)}
                    </select>
                  </label>
                ))}
              </>
            ) : null}
          </div>
          <button type="button" className={s.btn} onClick={() => setSt(DEFAULT_STATE)}>Reset view</button>
        </section>

        <nav aria-label="Drill-down" className={s.crumbs}>
          <ol>
            {[{ id: 'root', name: 'All regions' }, ...st.path.map((id) => ({ id, name: nodeName(id) }))].map((c, i, arr) => (
              <li key={c.id}>
                {i < arr.length - 1
                  ? <button type="button" className={s.crumbBtn} onClick={() => update({ path: st.path.slice(0, i) })}>{c.name}</button>
                  : <span aria-current="location" className={s.crumbHere}>{c.name}</span>}
              </li>
            ))}
          </ol>
        </nav>

        <div className={s.views}>
          <section className={s.panel} aria-labelledby={`${uid}-sc`}>
            <h3 id={`${uid}-sc`} className={s.panelTitle}>Altitude against cup score</h3>
            <p className={s.sub}>Each mark is a lot. Drag across the plot to brush both ranges; click a mark to pin it. Score axis starts at 80. <span className={s.sample}>Sample data</span></p>
            <ul className={s.legend} aria-label="Legend">
              {st.cmp ? (<>
                <li><span className={s.lgA} aria-hidden="true" />A: {optLabel(st.cmp.dim, st.cmp.a)} ({groupA.length})</li>
                <li><span className={s.lgB} aria-hidden="true" />B: {optLabel(st.cmp.dim, st.cmp.b)} ({groupB.length})</li>
                <li><span className={s.lgCtx} aria-hidden="true" />Other lots</li>
              </>) : (<>
                {PROCESSES.map((p) => <li key={p.id}><svg viewBox="-6 -6 12 12" className={s.lgShape} data-mark={p.id} aria-hidden="true">{p.id === 'washed' ? <circle r={4} /> : p.id === 'natural' ? <rect x={-3.5} y={-3.5} width={7} height={7} /> : <path d="M0 -4.6L4.2 3L-4.2 3Z" />}</svg>{p.label}</li>)}
                <li><span className={s.lgCtx} aria-hidden="true" />Outside the brush</li>
                <li><span className={s.lgTrend} aria-hidden="true" />Least-squares line</li>
              </>)}
            </ul>
            <Scatter lots={universe} inSel={inSel} markOf={markOf} alt={st.alt} score={st.score} pinned={st.pin}
              onBrush={(alt, score) => update({ alt, score })} onPin={(pin) => update({ pin })} describe={describe} trend={st.cmp ? null : trend} />
            <p className={s.axisTitle}><span>Altitude, metres</span><span>Cup score, points (vertical)</span></p>
            <p className={s.stripLabel} id={`${uid}-alt`}>Altitude range — drag, or use the handles with arrow keys (Shift for 100 m)</p>
            <RangeBrush domain={ALT} step={10} big={100} value={st.alt} onChange={(alt) => update({ alt })} label="altitude" describedBy={`${uid}-alt`}
              format={(v) => `${fmt.int.format(v)} m`} margin={{ left: SCATTER_M.left, right: SCATTER_M.right }} height={44}>
              {(x, _w, h) => {
                const m = Math.max(1, ...altBins.map((b) => b.n));
                return <svg width="100%" height={h} className={s.stripSvg} aria-hidden="true">{altBins.map((b) => <rect key={b.lo} x={x(b.lo) + 1} width={Math.max(0, x(b.lo + 100) - x(b.lo) - 2)} y={h - 4 - (b.n / m) * (h - 10)} height={(b.n / m) * (h - 10)} className={s.altBar} />)}</svg>;
              }}
            </RangeBrush>
          </section>

          <div className={s.sideViews}>
            <section className={s.panel} aria-labelledby={`${uid}-hist`}>
              <h3 id={`${uid}-hist`} className={s.panelTitle}>Score distribution</h3>
              <p className={s.sub}>{st.cmp ? 'Share of each group’s lots per 0.5-point bin, so groups of different size compare fairly.' : 'Lots per 0.5-point bin; the outline is everything in view, the fill is what the brushes select.'} Drag across to brush a score range.</p>
              <RangeBrush domain={SCORE} step={0.25} big={1} value={st.score} onChange={(score) => update({ score })} label="score"
                format={(v) => `${fmt.score(v)} points`} margin={H_MARGIN} height={196} inset={22}>
                {(x, w, h) => {
                  const top = 10, bottom = h - 24;
                  const yMax = scaleLinear().domain([0, maxBin]).nice(3).domain()[1];
                  const yv = (v: number) => bottom - (v / yMax) * (bottom - top);
                  const ticks = scaleLinear().domain([0, yMax]).ticks(3);
                  let step = '';
                  if (st.cmp) bins.forEach((b, i) => { const v = b.b / Math.max(1, groupB.length); step += `${i ? 'L' : 'M'}${x(b.lo).toFixed(1)} ${yv(v).toFixed(1)}H${x(b.lo + BIN).toFixed(1)}`; });
                  return (
                    <svg width={w} height={h} className={s.histSvg} aria-hidden="true">
                      {ticks.map((t) => (
                        <g key={t} transform={`translate(0 ${yv(t)})`}>
                          <line x1={H_MARGIN.left} x2={w - H_MARGIN.right} className={t === 0 ? s.base : s.grid} />
                          <text x={H_MARGIN.left - 6} y={4} textAnchor="end" className={s.tick}>{st.cmp ? fmt.pct.format(t) : t}</text>
                        </g>
                      ))}
                      {[80, 82, 84, 86, 88, 90].map((t) => <text key={t} x={x(t)} y={h - 6} textAnchor={t === 80 ? 'start' : t === 90 ? 'end' : 'middle'} className={s.tick}>{t}</text>)}
                      {st.cmp ? (
                        <>
                          {bins.map((b) => <rect key={b.lo} x={x(b.lo) + 1.5} width={Math.max(0, x(b.lo + BIN) - x(b.lo) - 3)} y={yv(b.a / Math.max(1, groupA.length))} height={bottom - yv(b.a / Math.max(1, groupA.length))} className={s.barA} />)}
                          <path d={step} className={s.stepB} />
                        </>
                      ) : bins.map((b) => (
                        <g key={b.lo}>
                          <rect x={x(b.lo) + 1} width={Math.max(0, x(b.lo + BIN) - x(b.lo) - 2)} y={yv(b.all)} height={bottom - yv(b.all)} className={s.barAll} />
                          <rect x={x(b.lo) + 1} width={Math.max(0, x(b.lo + BIN) - x(b.lo) - 2)} y={yv(b.sel)} height={bottom - yv(b.sel)} className={s.barSel} />
                        </g>
                      ))}
                    </svg>
                  );
                }}
              </RangeBrush>
              <div className={s.inlineRow}>
                <button type="button" className={s.linkBtn} aria-expanded={showBins} aria-controls={`${uid}-bins`} onClick={() => setShowBins((v) => !v)}>{showBins ? 'Hide bin table' : 'View bins as table'}</button>
                <span className={s.hint}>Score brush: {st.score ? `${fmt.score(st.score[0])}–${fmt.score(st.score[1])}` : 'off'}</span>
              </div>
              <div id={`${uid}-bins`} hidden={!showBins} className={s.tableBox} role="region" aria-label="Score bins, table" tabIndex={showBins ? 0 : -1}>
                {showBins ? (
                  <table className={s.table}>
                    <caption className={s.caption}>Lots per 0.5-point score bin. Sample data.</caption>
                    <thead><tr><th scope="col">Score bin</th><th scope="col" className={s.num}>In view</th><th scope="col" className={s.num}>Selected</th>{st.cmp ? <><th scope="col" className={s.num}>A</th><th scope="col" className={s.num}>B</th></> : null}</tr></thead>
                    <tbody>{bins.map((b) => <tr key={b.lo}><th scope="row">{fmt.score(b.lo)}–{fmt.score(b.lo + BIN)}</th><td className={s.num}>{b.all}</td><td className={s.num}>{b.sel}</td>{st.cmp ? <><td className={s.num}>{b.a}</td><td className={s.num}>{b.b}</td></> : null}</tr>)}</tbody>
                  </table>
                ) : null}
              </div>
            </section>

            <section className={s.panel} aria-labelledby={`${uid}-bd`}>
              <h3 id={`${uid}-bd`} className={s.panelTitle}>{leaf ? `Lots at ${nodeName(st.path[2])}` : `By ${childNoun}`}</h3>
              <p className={s.sub}>{st.cmp ? 'A vs B mean score per group (filled dot A, hollow square B), sorted by the difference.' : leaf ? 'Each selected lot’s score; choose one to pin it.' : 'Mean score (dot) and 10th–90th percentile (line) of the selected lots, best first. Choose a row to drill down.'}</p>
              <Breakdown rows={rows} levelKey={st.path.join('/')} compare={!!st.cmp} noun="lot" onSelect={(r) => (r.drill ? update({ path: [...st.path, r.id] }) : update({ pin: st.pin === r.id ? null : r.id }))} />
              {rows.length === 0 ? <p className={s.empty}>No lots here match the filters.</p> : null}
            </section>
          </div>
        </div>

        <div className={s.readout}>
          <section className={s.summaryBlock} aria-labelledby={`${uid}-sum`}>
            <h3 id={`${uid}-sum`} className={s.label}>What the selection shows</h3>
            <p className={s.summary}>{summary}</p>
            {st.cmp ? (
              <table className={s.cmpTable}>
                <caption className={s.srOnly}>Comparison of group A and group B, sample data</caption>
                <thead><tr><th scope="col">Measure</th><th scope="col" className={s.num}>A · {optLabel(st.cmp.dim, st.cmp.a)}</th><th scope="col" className={s.num}>B · {optLabel(st.cmp.dim, st.cmp.b)}</th><th scope="col" className={s.num}>A − B</th></tr></thead>
                <tbody>
                  {([['Lots', sA.n, sB.n, 'n'], ['Mean score', sA.mean, sB.mean, 's'], ['Median score', sA.median, sB.median, 's'], ['90th percentile', sA.p90, sB.p90, 's'], ['Share at 86+', sA.share86, sB.share86, 'p']] as const).map(([k, a, b, t]) => (
                    <tr key={k}>
                      <th scope="row">{k}</th>
                      <td className={s.num}>{t === 'n' ? a : t === 'p' ? (Number.isFinite(a) ? fmt.pct.format(a) : '—') : fmt.mean(a)}</td>
                      <td className={s.num}>{t === 'n' ? b : t === 'p' ? (Number.isFinite(b) ? fmt.pct.format(b) : '—') : fmt.mean(b)}</td>
                      <td className={s.num}>{!Number.isFinite(a) || !Number.isFinite(b) ? '—' : t === 'n' ? fmt.signed1.format(a - b).replace(/\.0$/, '') : t === 'p' ? `${fmt.signed1.format((a - b) * 100)} pp` : fmt.signed1.format(a - b)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            ) : null}
          </section>
          <section className={s.pinBlock} aria-labelledby={`${uid}-pin`}>
            <h3 id={`${uid}-pin`} className={s.label}>Pinned lot</h3>
            {pinned ? (
              <>
                <p className={s.pinId}>{pinned.id}</p>
                <dl className={s.pinFacts}>
                  {[['Farm', nodeName(pinned.farm)], ['Cooperative', nodeName(pinned.coop)], ['Region', nodeName(pinned.region)], ['Altitude', `${fmt.int.format(pinned.altitude)} m`], ['Cup score', `${fmt.score(pinned.score)} pts`], ['Process', PROC_LABEL[pinned.process]], ['Variety', VAR_LABEL[pinned.variety]], ['Yield', `${fmt.int.format(pinned.yield)} kg/ha`], ['Harvest', String(pinned.harvest)]].map(([k, v]) => (
                    <div key={k}><dt>{k}</dt><dd>{v}</dd></div>
                  ))}
                </dl>
                <div className={s.inlineRow}>
                  <button type="button" className={s.btn} onClick={() => update({ path: [pinned.region, pinned.coop, pinned.farm] })}>Drill to its farm</button>
                  <button type="button" className={s.linkBtn} onClick={() => update({ pin: null })}>Unpin</button>
                </div>
              </>
            ) : <p className={s.hint}>Nothing pinned. Click a mark, press Enter on the focused plot, or choose a row in the table.</p>}
          </section>
        </div>

        <section className={s.lots} aria-labelledby={`${uid}-tbl`}>
          <div className={s.lotsHead}>
            <h3 id={`${uid}-tbl`} className={s.panelTitle}>Selected lots</h3>
            <p className={s.sub}>{selected.length} rows · same selection as the charts · sortable · <span className={s.sample}>Sample data</span></p>
          </div>
          <div className={s.tableBox} role="region" aria-labelledby={`${uid}-tbl`} tabIndex={0}>
            <table className={`${s.table} ${s.lotTable}`}>
              <caption className={s.srOnly}>Selected sample lots; the pin button in each row pins that lot in every view.</caption>
              <thead>
                <tr>
                  {COLS.map((c) => (
                    <th key={c.key} scope="col" className={c.num ? s.num : undefined} aria-sort={st.sort.key === c.key ? (st.sort.dir === 1 ? 'ascending' : 'descending') : 'none'}>
                      <button type="button" className={s.sortBtn} onClick={() => sortBy(c.key)}>{c.label}<span aria-hidden="true">{st.sort.key === c.key ? (st.sort.dir === 1 ? ' ↑' : ' ↓') : ' ↕'}</span></button>
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {sorted.length ? sorted.map((l) => (
                  <tr key={l.id} data-pinned={l.id === st.pin || undefined}>
                    <th scope="row"><button type="button" className={s.pinBtn} aria-pressed={l.id === st.pin} onClick={() => update({ pin: st.pin === l.id ? null : l.id })}>{l.id}</button></th>
                    <td>{nodeName(l.farm)} <span className={s.muted}>· {nodeName(l.region)}</span></td>
                    <td className={s.num}>{fmt.int.format(l.altitude)}</td>
                    <td className={s.num}>{fmt.score(l.score)}</td>
                    <td className={s.num}>{fmt.int.format(l.yield)}</td>
                    <td><span className={s.swatch} data-mark={l.process} aria-hidden="true" />{PROC_LABEL[l.process]}</td>
                    <td>{VAR_LABEL[l.variety]}</td>
                  </tr>
                )) : <tr><td colSpan={COLS.length} className={s.empty}>No lots match. Reset the view or widen a brush.</td></tr>}
              </tbody>
            </table>
          </div>
        </section>

        <footer className={s.foot}>
          <p><strong>Data note.</strong> Sample data, seed {SEED}: {DATA.lots.length} lots in four invented regions, generated with an altitude trend (+0.29 points per 100 m), process and variety effects, a per-farm effect and noise, rounded to quarter points. Regions, cooperatives, farms and scores are fictional. Correlations here describe the generator, not coffee.</p>
        </footer>
      </div>
      <p className={s.srOnly} role="status" aria-live="polite">{announce}</p>
    </div>
  );
}

'use client';
/**
 * Ranked dot plot for the drill-down. Rows keep their identity while filters change: values are interpolated and rows
 * glide to their new rank together (the bar-race-transition recipe's technique, effects/bar-race-transition), drawn as
 * dots and 10th–90th percentile whiskers because cup scores cluster far from zero — bars would need a zero baseline
 * and would hide every difference. Changing level swaps identities, so it cuts instead of tweening.
 */
import { useEffect, useRef, useState } from 'react';
import { easeCubicInOut } from 'd3';
import { duration as D, useStudioMotion } from '../../../motion';
import { SCORE, fmt } from './data';
import s from './styles.module.css';

export interface Row { id: string; name: string; n: number; mean: number; p10: number; p90: number; a: number; b: number; drill: boolean; pinned?: boolean }
interface Vals { mean: number; p10: number; p90: number; a: number; b: number; rank: number }
const ROW = 40;
const pos = (v: number) => `${(((Math.min(SCORE[1], Math.max(SCORE[0], v)) - SCORE[0]) / (SCORE[1] - SCORE[0])) * 100).toFixed(2)}%`;

function ranked(rows: Row[], compare: boolean): Map<string, Vals> {
  const key = (r: Row) => (compare ? (Number.isFinite(r.a) && Number.isFinite(r.b) ? r.a - r.b : -Infinity) : Number.isFinite(r.mean) ? r.mean : -Infinity);
  const order = [...rows].sort((p, q) => key(q) - key(p) || p.name.localeCompare(q.name));
  return new Map(order.map((r, i) => [r.id, { mean: r.mean, p10: r.p10, p90: r.p90, a: r.a, b: r.b, rank: i }]));
}

export function Breakdown({ rows, levelKey, compare, onSelect, noun }: { rows: Row[]; levelKey: string; compare: boolean; onSelect: (r: Row) => void; noun: string }) {
  const { reduced, scale } = useStudioMotion();
  const target = ranked(rows, compare);
  const [shown, setShown] = useState(target);
  const shownRef = useRef(shown);
  shownRef.current = shown;
  const prevLevel = useRef(levelKey);
  const sig = rows.map((r) => `${r.id}:${r.mean}:${r.a}:${r.b}`).join('|') + String(compare);

  useEffect(() => {
    const t = ranked(rows, compare);
    const levelChanged = prevLevel.current !== levelKey;
    prevLevel.current = levelKey;
    const from = shownRef.current;
    if (levelChanged || reduced || ![...t.keys()].every((k) => from.has(k))) { setShown(t); return; }
    const dur = D.moderate * scale.duration;
    let raf = 0, t0 = 0;
    const mix = (p: number, q: number, e: number) => (Number.isFinite(p) && Number.isFinite(q) ? p + (q - p) * e : q);
    const frame = (now: number) => {
      if (!t0) t0 = now;
      const p = Math.min(1, (now - t0) / dur);
      const e = easeCubicInOut(p);
      const next = new Map<string, Vals>();
      for (const [k, to] of t) {
        const f = from.get(k)!;
        next.set(k, { mean: mix(f.mean, to.mean, e), p10: mix(f.p10, to.p10, e), p90: mix(f.p90, to.p90, e), a: mix(f.a, to.a, e), b: mix(f.b, to.b, e), rank: f.rank + (to.rank - f.rank) * e });
      }
      setShown(next);
      if (p < 1) raf = requestAnimationFrame(frame);
    };
    raf = requestAnimationFrame(frame);
    return () => cancelAnimationFrame(raf);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sig, levelKey, reduced, scale.duration]);

  const ticks = [80, 82, 84, 86, 88, 90];
  return (
    <div className={s.dots}>
      <div className={s.dotAxis} aria-hidden="true">
        <span />
        <span className={s.dotAxisTrack}>{ticks.map((t) => <span key={t} style={{ left: pos(t) }}>{t}</span>)}</span>
        <span />
      </div>
      <ol className={s.dotList} style={{ height: rows.length * ROW }}>
        {rows.map((r) => {
          const v = shown.get(r.id) ?? target.get(r.id)!;
          const empty = compare ? !(Number.isFinite(r.a) && Number.isFinite(r.b)) : !r.n;
          const detail = empty
            ? (compare ? ': not enough lots in both groups.' : ': no lots match.')
            : compare
              ? ` points, group A minus group B (A mean ${fmt.mean(r.a)}, B mean ${fmt.mean(r.b)}).${r.drill ? ' Drill down.' : ''}`
              : ` mean score${r.n > 1 ? `; 10th to 90th percentile ${fmt.mean(r.p10)} to ${fmt.mean(r.p90)}` : ''}.${r.drill ? ' Drill down.' : ''}`;
          return (
            <li key={r.id} className={s.dotRow} style={{ transform: `translateY(${(v.rank * ROW).toFixed(1)}px)` }}>
              <button type="button" className={s.dotBtn} onClick={() => onSelect(r)} aria-pressed={r.drill ? undefined : !!r.pinned} disabled={empty && r.drill}>
                <span className={s.dotName}><span className={s.dotNameText}>{r.name}</span><span className={s.dotN}>{r.n ? `n ${r.n}` : 'n 0'}</span></span>
                <span className={s.dotTrack} aria-hidden="true">
                  {empty ? null : compare ? (
                    <>
                      <span className={s.dumbbell} style={{ left: pos(Math.min(v.a, v.b)), right: `calc(100% - ${pos(Math.max(v.a, v.b))})` }} />
                      <span className={s.dotA} style={{ left: pos(v.a) }} />
                      <span className={s.dotB} style={{ left: pos(v.b) }} />
                    </>
                  ) : (
                    <>
                      {r.n > 1 && <span className={s.whisker} style={{ left: pos(v.p10), right: `calc(100% - ${pos(v.p90)})` }} />}
                      <span className={s.dot} data-pinned={r.pinned || undefined} style={{ left: pos(v.mean) }} />
                    </>
                  )}
                </span>
                <span className={s.dotVal}>{empty ? '—' : compare ? fmt.signed1.format(r.a - r.b) : fmt.mean(r.mean)}</span>
                <span className={s.srOnly}>{detail}</span>
                {r.drill ? <span className={s.chev} aria-hidden="true">›</span> : <span className={s.chev} aria-hidden="true" />}
              </button>
            </li>
          );
        })}
      </ol>
    </div>
  );
}

/**
 * Cupping-lot explorer — SAMPLE DATA. Four fictional growing regions, their cooperatives, farms and lots are generated
 * from one seed: altitude by region/coop/farm, a cup score with an altitude trend, process and variety effects, a farm
 * effect and noise (rounded to quarter points like a cupping form), and a yield that falls with altitude. Nothing here
 * describes a real origin, producer or harvest.
 */
export const SEED = 1730;
export const ALT: readonly [number, number] = [900, 2300];
export const SCORE: readonly [number, number] = [80, 90];

export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export type Process = 'washed' | 'natural' | 'honey';
export type Variety = 'bourbon' | 'typica' | 'caturra' | 'hybrid';
export type Level = 'root' | 'region' | 'coop' | 'farm';
export const PROCESSES: readonly { id: Process; label: string }[] = [{ id: 'washed', label: 'Washed' }, { id: 'natural', label: 'Natural' }, { id: 'honey', label: 'Honey' }];
export const VARIETIES: readonly { id: Variety; label: string }[] = [{ id: 'bourbon', label: 'Bourbon' }, { id: 'typica', label: 'Typica' }, { id: 'caturra', label: 'Caturra' }, { id: 'hybrid', label: 'Hybrid' }];
const PROC_FX: Record<Process, number> = { washed: 0, natural: 0.35, honey: 0.2 };
const VAR_FX: Record<Variety, number> = { bourbon: 0.3, typica: 0.45, caturra: 0, hybrid: -0.7 };

const REGIONS = [
  { id: 'kr', name: 'Kettle Ridge', base: 1650, coops: ['Upper Terraces', 'Mill Brook'] },
  { id: 'mb', name: 'Morrow Basin', base: 1220, coops: ['Basin Growers', 'Ferry Road', 'Lowfield'] },
  { id: 'sh', name: 'Sable Hills', base: 1880, coops: ['High Sable', 'Crown Pass'] },
  { id: 'lv', name: 'Lantern Valley', base: 1460, coops: ['Lantern North', 'Weir Side', 'Orchard Bend'] },
] as const;
const PRE = ['Ash', 'Bramble', 'Cinder', 'Dove', 'Elm', 'Fallow', 'Gorse', 'Hazel', 'Ivy', 'Juniper', 'Kestrel', 'Lark', 'Mill', 'Nettle', 'Oak', 'Pine', 'Quarry', 'Rook', 'Sloe', 'Thorn', 'Vetch', 'Wren', 'Yarrow', 'Bracken'];
const SUF = ['grove', 'hill', 'patch', 'cote', 'stead', 'mere', 'end', 'rise', 'shelf', 'bank', 'field', 'fold', 'edge', 'croft', 'top', 'wood'];

export interface TreeNode { id: string; name: string; level: Exclude<Level, 'root'>; parent: string | null }
export interface Lot {
  id: string; region: string; coop: string; farm: string;
  altitude: number; score: number; yield: number; process: Process; variety: Variety; harvest: number;
}

export function buildDataset(seed = SEED): { nodes: Map<string, TreeNode>; lots: Lot[] } {
  const rnd = mulberry32(seed);
  const g = () => { let u = 0; while (u === 0) u = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * rnd()); };
  const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));
  const nodes = new Map<string, TreeNode>();
  const lots: Lot[] = [];
  const used = new Set<string>();
  const farmName = () => {
    for (;;) {
      const n = PRE[Math.floor(rnd() * PRE.length)] + SUF[Math.floor(rnd() * SUF.length)];
      if (!used.has(n)) { used.add(n); return n; }
    }
  };
  for (const r of REGIONS) {
    nodes.set(r.id, { id: r.id, name: r.name, level: 'region', parent: null });
    r.coops.forEach((cName, ci) => {
      const cid = `${r.id}.${ci + 1}`;
      nodes.set(cid, { id: cid, name: cName, level: 'coop', parent: r.id });
      const coopAlt = r.base + g() * 110;
      const farms = 4 + Math.floor(rnd() * 3);
      for (let fi = 0; fi < farms; fi++) {
        const fid = `${cid}.${fi + 1}`;
        nodes.set(fid, { id: fid, name: farmName(), level: 'farm', parent: cid });
        const farmAlt = coopAlt + g() * 130;
        const farmFx = g() * 0.55;
        const mainVar = VARIETIES[Math.floor(rnd() * VARIETIES.length)].id;
        const mainProc = PROCESSES[Math.floor(rnd() * PROCESSES.length)].id;
        const count = 4 + Math.floor(rnd() * 6);
        for (let li = 0; li < count; li++) {
          const altitude = Math.round(clamp(farmAlt + g() * 55, ALT[0] + 20, ALT[1] - 20) / 5) * 5;
          const variety = rnd() < 0.7 ? mainVar : VARIETIES[Math.floor(rnd() * VARIETIES.length)].id;
          const process = rnd() < 0.6 ? mainProc : PROCESSES[Math.floor(rnd() * PROCESSES.length)].id;
          const raw = 82.8 + 0.0029 * (altitude - 1000) + PROC_FX[process] + VAR_FX[variety] + farmFx + g() * (process === 'natural' ? 0.8 : 0.55);
          lots.push({
            id: `${r.id.toUpperCase()}-${ci + 1}${String(fi + 1).padStart(2, '0')}-${li + 1}`,
            region: r.id, coop: cid, farm: fid, altitude, process, variety,
            score: Math.round(clamp(raw, SCORE[0] + 0.25, SCORE[1] - 0.25) * 4) / 4,
            yield: Math.round(clamp(2600 - 0.55 * altitude + g() * 240 + (variety === 'hybrid' ? 380 : 0), 380, 2600) / 10) * 10,
            harvest: rnd() < 0.5 ? 2025 : 2026,
          });
        }
      }
    });
  }
  return { nodes, lots };
}

/* ── statistics ─────────────────────────────────────────────── */
export const mean = (v: number[]): number => (v.length ? v.reduce((a, b) => a + b, 0) / v.length : NaN);
export function quantile(sorted: number[], q: number): number {
  if (!sorted.length) return NaN;
  const p = (sorted.length - 1) * q, i = Math.floor(p), f = p - i;
  return i + 1 < sorted.length ? sorted[i] + (sorted[i + 1] - sorted[i]) * f : sorted[i];
}
export function pearson(xs: number[], ys: number[]): number {
  const n = xs.length;
  if (n < 3) return NaN;
  const mx = mean(xs), my = mean(ys);
  let sxy = 0, sxx = 0, syy = 0;
  for (let i = 0; i < n; i++) { const dx = xs[i] - mx, dy = ys[i] - my; sxy += dx * dy; sxx += dx * dx; syy += dy * dy; }
  return sxx && syy ? sxy / Math.sqrt(sxx * syy) : NaN;
}
export interface Summary { n: number; mean: number; median: number; p10: number; p90: number; share86: number }
export function summarise(lots: Lot[]): Summary {
  const s = lots.map((l) => l.score).sort((a, b) => a - b);
  return { n: s.length, mean: mean(s), median: quantile(s, 0.5), p10: quantile(s, 0.1), p90: quantile(s, 0.9), share86: s.length ? s.filter((v) => v >= 86).length / s.length : NaN };
}

/* ── URL-hash state ─────────────────────────────────────────── */
export type CompareDim = 'process' | 'variety' | 'region';
export type SortKey = 'id' | 'farm' | 'altitude' | 'score' | 'yield' | 'process' | 'variety';
export interface ViewState {
  proc: Process[];
  vari: Variety[];
  /** Drill-down path of node ids, root first (region, coop, farm). */
  path: string[];
  alt: [number, number] | null;
  score: [number, number] | null;
  cmp: { dim: CompareDim; a: string; b: string } | null;
  sort: { key: SortKey; dir: 1 | -1 };
  pin: string | null;
}
export const DEFAULT_STATE: ViewState = {
  proc: PROCESSES.map((p) => p.id), vari: VARIETIES.map((v) => v.id), path: [], alt: null, score: null, cmp: null,
  sort: { key: 'score', dir: -1 }, pin: null,
};
const SORT_KEYS: readonly SortKey[] = ['id', 'farm', 'altitude', 'score', 'yield', 'process', 'variety'];

export function encodeState(s: ViewState): string {
  const q = new URLSearchParams();
  if (s.proc.length !== PROCESSES.length) q.set('process', s.proc.join(','));
  if (s.vari.length !== VARIETIES.length) q.set('variety', s.vari.join(','));
  if (s.path.length) q.set('at', s.path[s.path.length - 1]);
  if (s.alt) q.set('alt', `${s.alt[0]}-${s.alt[1]}`);
  if (s.score) q.set('score', `${s.score[0]}-${s.score[1]}`);
  if (s.cmp) q.set('compare', `${s.cmp.dim}:${s.cmp.a}:${s.cmp.b}`);
  if (s.sort.key !== 'score' || s.sort.dir !== -1) q.set('sort', `${s.sort.key}:${s.sort.dir === 1 ? 'asc' : 'desc'}`);
  if (s.pin) q.set('lot', s.pin);
  return q.toString().replace(/%2C/g, ',').replace(/%3A/g, ':');
}

export function decodeState(hash: string, nodes: Map<string, TreeNode>, lotIds: Set<string>): ViewState {
  const q = new URLSearchParams(hash.replace(/^#/, ''));
  const list = <T extends string>(v: string | null, all: readonly { id: T }[]): T[] => {
    if (v === null) return all.map((x) => x.id);
    const ids = v.split(',').filter((x): x is T => all.some((a) => a.id === x));
    return ids.length ? ids : all.map((x) => x.id);
  };
  const range = (v: string | null, lim: readonly [number, number]): [number, number] | null => {
    const m = v?.match(/^(-?[\d.]+)-(-?[\d.]+)$/);
    if (!m) return null;
    const a = Math.max(lim[0], Number(m[1])), b = Math.min(lim[1], Number(m[2]));
    return Number.isFinite(a) && Number.isFinite(b) && b > a ? [a, b] : null;
  };
  const path: string[] = [];
  for (let id = q.get('at'); id && nodes.has(id); id = nodes.get(id)!.parent) path.unshift(id);
  const [dim, a, b] = (q.get('compare') ?? '').split(':');
  const dims: Record<CompareDim, readonly { id: string }[]> = { process: PROCESSES, variety: VARIETIES, region: [...nodes.values()].filter((n) => n.level === 'region') };
  const cmp = (dim === 'process' || dim === 'variety' || dim === 'region') && dims[dim].some((x) => x.id === a) && dims[dim].some((x) => x.id === b) && a !== b ? { dim: dim as CompareDim, a, b } : null;
  const [sk, sd] = (q.get('sort') ?? '').split(':');
  const lot = q.get('lot');
  return {
    proc: list(q.get('process'), PROCESSES), vari: list(q.get('variety'), VARIETIES), path,
    alt: range(q.get('alt'), ALT), score: range(q.get('score'), SCORE), cmp,
    sort: SORT_KEYS.includes(sk as SortKey) ? { key: sk as SortKey, dir: sd === 'asc' ? 1 : -1 } : DEFAULT_STATE.sort,
    pin: lot && lotIds.has(lot) ? lot : null,
  };
}

const nf1 = new Intl.NumberFormat('en-GB', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const nf2 = new Intl.NumberFormat('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
export const fmt = {
  score: (v: number) => (Number.isFinite(v) ? nf2.format(v) : '—'),
  mean: (v: number) => (Number.isFinite(v) ? nf1.format(v) : '—'),
  int: new Intl.NumberFormat('en-GB', { maximumFractionDigits: 0 }),
  pct: new Intl.NumberFormat('en-GB', { style: 'percent', maximumFractionDigits: 0 }),
  signed1: new Intl.NumberFormat('en-GB', { minimumFractionDigits: 1, maximumFractionDigits: 1, signDisplay: 'exceptZero' }),
  r: new Intl.NumberFormat('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2, signDisplay: 'exceptZero' }),
};

'use client';
/**
 * One-dimensional brush over a chart. Technique from the brush-linked-range recipe (effects/brush-linked-range): the
 * window and both edges are real role="slider" controls (arrows step, Shift steps big, Home/End jump), pointer
 * capture drives drags, and dragging across empty chart draws a new range. Here it is generic: any domain, any
 * background chart (passed as a render function), and `null` means "no filter".
 */
import { useRef, useState, type KeyboardEvent, type PointerEvent, type ReactNode } from 'react';
import { scaleLinear, type ScaleLinear } from 'd3';
import { useElementSize } from '../../../motion';
import s from './styles.module.css';

type Part = 'start' | 'end' | 'window';
interface Props {
  domain: readonly [number, number];
  step: number;
  big: number;
  value: readonly [number, number] | null;
  onChange: (v: [number, number] | null) => void;
  label: string;
  format: (v: number) => string;
  margin: { left: number; right: number };
  height: number;
  describedBy?: string;
  /** Space kept free under the window and handles (for an axis label row). */
  inset?: number;
  children?: (x: ScaleLinear<number, number>, width: number, height: number) => ReactNode;
}

export function RangeBrush({ domain, step, big, value, onChange, label, format, margin, height, describedBy, inset = 0, children }: Props) {
  const ref = useRef<HTMLDivElement>(null);
  const { width } = useElementSize(ref);
  const [lo, hi] = domain;
  const v: [number, number] = value ? [value[0], value[1]] : [lo, hi];
  const x = scaleLinear().domain([lo, hi]).range([margin.left, Math.max(margin.left + 1, width - margin.right)]);
  const drag = useRef<{ part: Part | 'new'; px: number; v: [number, number]; moved: boolean } | null>(null);
  const [draft, setDraft] = useState<[number, number] | null>(null);
  const snap = (n: number) => Math.round(n / step) * step;
  const clampV = (n: number) => Math.min(hi, Math.max(lo, n));
  const emit = (a: number, b: number) => {
    const r: [number, number] = [clampV(Math.min(a, b)), clampV(Math.max(a, b))];
    onChange(r[0] <= lo && r[1] >= hi ? null : r);
  };
  const minSpan = step;
  const apply = (part: Part, base: [number, number], d: number): [number, number] => {
    if (part === 'start') return [Math.min(base[1] - minSpan, clampV(snap(base[0] + d))), base[1]];
    if (part === 'end') return [base[0], Math.max(base[0] + minSpan, clampV(snap(base[1] + d)))];
    const span = base[1] - base[0];
    const a = Math.min(hi - span, Math.max(lo, snap(base[0] + d)));
    return [a, a + span];
  };
  const valueAt = (clientX: number) => {
    const r = ref.current!.getBoundingClientRect();
    return clampV(x.invert(clientX - r.left));
  };

  const down = (part: Part | 'new') => (ev: PointerEvent<HTMLDivElement>) => {
    if (ev.button !== 0 || width <= 0) return;
    ev.stopPropagation();
    ev.currentTarget.setPointerCapture(ev.pointerId);
    drag.current = { part, px: ev.clientX, v, moved: false };
  };
  const move = (ev: PointerEvent<HTMLDivElement>) => {
    const g = drag.current;
    if (!g) return;
    if (!g.moved && Math.abs(ev.clientX - g.px) < 3) return;
    g.moved = true;
    if (g.part === 'new') { setDraft([valueAt(g.px), valueAt(ev.clientX)]); return; }
    const per = (hi - lo) / Math.max(1, x.range()[1] - x.range()[0]);
    const next = apply(g.part, g.v, (ev.clientX - g.px) * per);
    emit(next[0], next[1]);
  };
  const up = (ev: PointerEvent<HTMLDivElement>) => {
    const g = drag.current;
    drag.current = null;
    if (!g) return;
    if (g.part === 'new') {
      setDraft(null);
      if (!g.moved) { onChange(null); return; }
      const a = snap(valueAt(g.px)), b = snap(valueAt(ev.clientX));
      if (Math.abs(b - a) >= step) emit(a, b);
    }
  };
  const key = (part: Part) => (ev: KeyboardEvent<HTMLDivElement>) => {
    const d = ev.key === 'ArrowLeft' || ev.key === 'ArrowDown' ? -(ev.shiftKey ? big : step) : ev.key === 'ArrowRight' || ev.key === 'ArrowUp' ? (ev.shiftKey ? big : step)
      : ev.key === 'PageDown' ? -big : ev.key === 'PageUp' ? big : ev.key === 'Home' ? lo - hi : ev.key === 'End' ? hi - lo : 0;
    if (ev.key === 'Escape' && value) { ev.preventDefault(); onChange(null); return; }
    if (!d) return;
    ev.preventDefault();
    const next = apply(part, v, d);
    emit(next[0], next[1]);
  };

  const shown = draft ? [Math.min(draft[0], draft[1]), Math.max(draft[0], draft[1])] : v;
  const left = x(shown[0]), right = x(shown[1]);
  return (
    <div ref={ref} className={s.brush} style={{ height }} data-active={value || draft ? '' : undefined}
      onPointerDown={down('new')} onPointerMove={move} onPointerUp={up} onPointerCancel={() => { drag.current = null; setDraft(null); }}>
      {width > 0 && children ? children(x, width, height) : null}
      {(value || draft) && (
        <>
          <div className={s.shade} style={{ left: margin.left, width: Math.max(0, left - margin.left), bottom: inset }} />
          <div className={s.shade} style={{ left: right, width: Math.max(0, x.range()[1] - right), bottom: inset }} />
        </>
      )}
      <div
        className={s.window} style={{ left, width: Math.max(0, right - left), bottom: inset }}
        role="slider" tabIndex={0} aria-label={`Move ${label} range`} aria-describedby={describedBy}
        aria-valuemin={lo} aria-valuemax={hi - (v[1] - v[0])} aria-valuenow={v[0]}
        aria-valuetext={value ? `${format(v[0])} to ${format(v[1])}` : `All ${label} values, ${format(lo)} to ${format(hi)}`}
        onPointerDown={down('window')} onKeyDown={key('window')}
      />
      {(['start', 'end'] as const).map((part) => (
        <div
          key={part} className={s.handle} style={{ left: part === 'start' ? left : right, bottom: inset }}
          role="slider" tabIndex={0} aria-label={`${label[0].toUpperCase()}${label.slice(1)} ${part === 'start' ? 'from' : 'to'}`} aria-describedby={describedBy}
          aria-valuemin={part === 'start' ? lo : v[0] + minSpan} aria-valuemax={part === 'start' ? v[1] - minSpan : hi}
          aria-valuenow={part === 'start' ? v[0] : v[1]} aria-valuetext={format(part === 'start' ? v[0] : v[1])}
          onPointerDown={down(part)} onKeyDown={key(part)}
        ><span /></div>
      ))}
    </div>
  );
}

'use client';
import { useMemo, useRef, useState, type KeyboardEvent, type PointerEvent } from 'react';
import { scaleLinear } from 'd3';
import { useElementSize } from '../../../motion';
import { ALT, SCORE, fmt, type Lot } from './data';
import s from './styles.module.css';

export type Mark = 'washed' | 'natural' | 'honey' | 'a' | 'b';
export const SCATTER_M = { top: 14, right: 14, bottom: 30, left: 46 };

interface Props {
  lots: Lot[];
  inSel: (l: Lot) => boolean;
  markOf: (l: Lot) => Mark | null;
  alt: readonly [number, number] | null;
  score: readonly [number, number] | null;
  onBrush: (alt: [number, number] | null, score: [number, number] | null) => void;
  pinned: string | null;
  onPin: (id: string | null) => void;
  describe: (l: Lot) => string;
  trend: { slope: number; intercept: number; r: number; x0: number; x1: number } | null;
}

function Shape({ mark, x, y, r }: { mark: Mark; x: number; y: number; r: number }) {
  if (mark === 'natural' || mark === 'b') return <rect x={x - r * 0.88} y={y - r * 0.88} width={r * 1.76} height={r * 1.76} />;
  if (mark === 'honey') return <path d={`M${x} ${y - r * 1.15}L${x + r * 1.05} ${y + r * 0.75}L${x - r * 1.05} ${y + r * 0.75}Z`} />;
  return <circle cx={x} cy={y} r={r} />;
}

export function Scatter({ lots, inSel, markOf, alt, score, onBrush, pinned, onPin, describe, trend }: Props) {
  const ref = useRef<HTMLDivElement>(null);
  const { width, height } = useElementSize(ref);
  const M = SCATTER_M;
  const x = scaleLinear().domain(ALT).range([M.left, Math.max(M.left + 1, width - M.right)]);
  const y = scaleLinear().domain(SCORE).range([Math.max(M.top + 1, height - M.bottom), M.top]);
  const drag = useRef<{ x0: number; y0: number; moved: boolean } | null>(null);
  const [draft, setDraft] = useState<[number, number, number, number] | null>(null);
  const [hover, setHover] = useState<Lot | null>(null);
  const [cursor, setCursor] = useState<number | null>(null);

  const order = useMemo(() => lots.filter(inSel).sort((a, b) => a.altitude - b.altitude || a.score - b.score || a.id.localeCompare(b.id)), [lots, inSel]);
  const cur = cursor !== null && order.length ? order[Math.min(cursor, order.length - 1)] : null;
  const active = cur ?? hover;

  const local = (ev: PointerEvent<HTMLDivElement>) => { const r = ev.currentTarget.getBoundingClientRect(); return { px: ev.clientX - r.left, py: ev.clientY - r.top }; };
  const nearest = (px: number, py: number, radius = 14): Lot | null => {
    let best: Lot | null = null, bd = radius * radius;
    for (const l of lots) { const dx = x(l.altitude) - px, dy = y(l.score) - py, d = dx * dx + dy * dy; if (d < bd) { bd = d; best = l; } }
    return best;
  };
  const onDown = (ev: PointerEvent<HTMLDivElement>) => {
    if (ev.button !== 0) return;
    ev.currentTarget.setPointerCapture(ev.pointerId);
    const p = local(ev);
    drag.current = { x0: p.px, y0: p.py, moved: false };
  };
  const onMove = (ev: PointerEvent<HTMLDivElement>) => {
    const p = local(ev);
    const g = drag.current;
    if (!g) { setHover(nearest(p.px, p.py)); return; }
    if (!g.moved && Math.hypot(p.px - g.x0, p.py - g.y0) < 5) return;
    g.moved = true;
    setHover(null);
    setDraft([g.x0, g.y0, p.px, p.py]);
  };
  const onUp = (ev: PointerEvent<HTMLDivElement>) => {
    const g = drag.current;
    drag.current = null;
    if (!g) return;
    const p = local(ev);
    if (!g.moved) {
      const hit = nearest(p.px, p.py);
      if (hit) onPin(hit.id === pinned ? null : hit.id);
      else { onPin(null); if (alt || score) onBrush(null, null); }
      return;
    }
    setDraft(null);
    const a0 = Math.round(x.invert(Math.min(g.x0, p.px)) / 10) * 10, a1 = Math.round(x.invert(Math.max(g.x0, p.px)) / 10) * 10;
    const s0 = Math.round(y.invert(Math.max(g.y0, p.py)) * 4) / 4, s1 = Math.round(y.invert(Math.min(g.y0, p.py)) * 4) / 4;
    const ca = (v: number) => Math.min(ALT[1], Math.max(ALT[0], v)), cs = (v: number) => Math.min(SCORE[1], Math.max(SCORE[0], v));
    onBrush(a1 - a0 >= 20 ? [ca(a0), ca(a1)] : null, s1 - s0 >= 0.25 ? [cs(s0), cs(s1)] : null);
  };
  const onKey = (ev: KeyboardEvent<HTMLDivElement>) => {
    if (!order.length) return;
    if (ev.key === 'Escape') { setCursor(null); return; }
    if ((ev.key === 'Enter' || ev.key === ' ') && cur) { ev.preventDefault(); onPin(cur.id === pinned ? null : cur.id); return; }
    const c = cursor ?? 0;
    const next = ev.key === 'ArrowRight' || ev.key === 'ArrowUp' ? c + 1 : ev.key === 'ArrowLeft' || ev.key === 'ArrowDown' ? c - 1
      : ev.key === 'PageUp' ? c + 10 : ev.key === 'PageDown' ? c - 10 : ev.key === 'Home' ? 0 : ev.key === 'End' ? order.length - 1 : null;
    if (next === null) return;
    ev.preventDefault();
    setCursor(Math.min(order.length - 1, Math.max(0, next)));
  };

  const ready = width > 80 && height > 80;
  const bx0 = alt ? x(alt[0]) : M.left, bx1 = alt ? x(alt[1]) : x.range()[1];
  const by0 = score ? y(score[1]) : M.top, by1 = score ? y(score[0]) : y.range()[0];
  const pinnedLot = pinned ? lots.find((l) => l.id === pinned) ?? null : null;

  return (
    <div ref={ref} className={s.scatter}>
      {ready && (
        <svg width={width} height={height} aria-hidden="true" className={s.svg}>
          {y.ticks(10).map((t) => (
            <g key={`y${t}`} transform={`translate(0 ${y(t)})`}>
              <line x1={M.left} x2={x.range()[1]} className={s.grid} />
              <text x={M.left - 8} y={4} textAnchor="end" className={s.tick}>{t}</text>
            </g>
          ))}
          {x.ticks(width < 520 ? 4 : 7).map((t) => (
            <g key={`x${t}`} transform={`translate(${x(t)} 0)`}>
              <line y1={M.top} y2={y.range()[0]} className={s.grid} />
              <text y={y.range()[0] + 18} textAnchor="middle" className={s.tick}>{fmt.int.format(t)}</text>
            </g>
          ))}
          {(alt || score) && <rect x={bx0} y={by0} width={Math.max(0, bx1 - bx0)} height={Math.max(0, by1 - by0)} className={s.brushRect} />}
          {lots.filter((l) => !inSel(l) || !markOf(l)).map((l) => <g key={l.id} className={s.ctx}><Shape mark={markOf(l) ?? 'washed'} x={x(l.altitude)} y={y(l.score)} r={3.2} /></g>)}
          {lots.filter((l) => inSel(l) && markOf(l)).map((l) => <g key={l.id} className={s.pt} data-mark={markOf(l)!}><Shape mark={markOf(l)!} x={x(l.altitude)} y={y(l.score)} r={3.6} /></g>)}
          {trend && (
            <g className={s.trend}>
              <line x1={x(trend.x0)} x2={x(trend.x1)} y1={y(trend.intercept + trend.slope * trend.x0)} y2={y(trend.intercept + trend.slope * trend.x1)} />
              <text x={x(trend.x1) - 4} y={y(trend.intercept + trend.slope * trend.x1) - 8} textAnchor="end">r = {fmt.r.format(trend.r)}</text>
            </g>
          )}
          {pinnedLot && <circle cx={x(pinnedLot.altitude)} cy={y(pinnedLot.score)} r={8} className={s.pinRing} />}
          {active && <circle cx={x(active.altitude)} cy={y(active.score)} r={6.5} className={s.focusRing} />}
          {draft && <rect x={Math.min(draft[0], draft[2])} y={Math.min(draft[1], draft[3])} width={Math.abs(draft[2] - draft[0])} height={Math.abs(draft[3] - draft[1])} className={s.draftRect} />}
        </svg>
      )}
      {active && ready && (
        <div className={s.tip} data-side={x(active.altitude) > width * 0.6 ? 'left' : 'right'} style={{ transform: `translate(${x(active.altitude)}px, ${y(active.score)}px)` }} aria-hidden="true">
          <div><strong>{active.id}</strong><span>{describe(active)}</span></div>
        </div>
      )}
      <div
        className={s.hit}
        role="slider"
        tabIndex={0}
        aria-label="Lots in the scatter plot. Arrow keys step through the selected lots by altitude, Enter pins one, Escape hides the readout."
        aria-valuemin={order.length ? 1 : 0}
        aria-valuemax={order.length}
        aria-valuenow={cur ? Math.min(cursor!, order.length - 1) + 1 : 0}
        aria-valuetext={cur ? `${cur.id}: ${describe(cur)}${cur.id === pinned ? ', pinned' : ''}` : `${order.length} selected lots. Use the arrow keys to step through them.`}
        onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp}
        onPointerLeave={() => setHover(null)} onPointerCancel={() => { drag.current = null; setDraft(null); }}
        onFocus={() => setCursor((c) => c ?? Math.max(0, order.findIndex((l) => l.id === pinned)))}
        onBlur={() => setCursor(null)}
        onKeyDown={onKey}
      />
    </div>
  );
}

/* Four Valleys — a cupping form crossed with a field notebook: serif questions, mono figures, graph-paper plots,
   two ink colours of its own (cobalt for washed lots, ochre for honey) beside the theme's signal. */
.root {
  --de-washed: #2a5db0;
  --de-honey: #8a5a00;
  --de-natural: var(--s3-signal, #bf2f09);
  container-type: inline-size;
  min-height: 100dvh;
  padding-bottom: 64px;
  background: var(--s3-bg, #f3f0e8);
  color: var(--s3-ink, #11110f);
  font-family: var(--s3-font-text, ui-sans-serif, system-ui, sans-serif);
  font-size: 0.875rem;
  line-height: 1.45;
}
:global([data-theme='dark']) .root { --de-washed: #8cb4ff; --de-honey: #f2b632; }
.wrap { max-width: 1440px; margin: 0 auto; padding-inline: clamp(16px, 2.4cqi, 32px); }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.label { margin: 0; font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.6875rem; font-weight: 500; letter-spacing: 0.08em; text-transform: uppercase; color: var(--s3-ink-muted, #5c5a52); }
.sub { margin: 4px 0 0; max-width: 70ch; font-size: 0.78rem; line-height: 1.45; color: var(--s3-ink-muted, #5c5a52); text-wrap: pretty; }
.hint { font-size: 0.75rem; color: var(--s3-ink-muted, #5c5a52); }
.muted { color: var(--s3-ink-muted, #5c5a52); }
.sample { display: inline-block; padding: 0 5px; border: 1px solid var(--s3-line-strong, #11110f); border-radius: 2px; font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.625rem; font-style: normal; line-height: 1.5; letter-spacing: 0.08em; text-transform: uppercase; color: var(--s3-ink, #11110f); white-space: nowrap; vertical-align: 0.1em; }

/* ── head ─────────────────────────────────────────────────────── */
.head { display: grid; gap: 10px; padding: clamp(24px, 4cqi, 48px) 0 20px; border-bottom: 1px solid var(--s3-line-strong, #11110f); }
@container (min-width: 1000px) { .head { grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr); column-gap: 48px; align-items: end; } .kicker { grid-column: 1 / -1; } }
.kicker { margin: 0; display: flex; flex-wrap: wrap; gap: 6px 10px; align-items: center; font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--s3-ink-muted, #5c5a52); }
.title { margin: 0; font-family: var(--s3-font-serif, Georgia, serif); font-size: clamp(2.1rem, 5.6cqi, 3.75rem); font-weight: 400; line-height: 1; letter-spacing: -0.015em; text-wrap: balance; }
.title em { font-style: italic; color: var(--s3-ink-muted, #5c5a52); }
.lede { margin: 0; max-width: 56ch; font-size: 0.9375rem; line-height: 1.55; color: var(--s3-ink-muted, #5c5a52); text-wrap: pretty; }

/* ── toolbar ──────────────────────────────────────────────────── */
.toolbar { display: flex; flex-wrap: wrap; align-items: flex-end; gap: 14px 28px; padding: 16px 0; border-bottom: 1px solid var(--s3-line, #11110f24); }
.facet { display: flex; flex-wrap: wrap; gap: 6px; margin: 0; padding: 0; border: 0; min-inline-size: 0; }
.facet legend { float: left; width: 100%; margin-bottom: 6px; padding: 0; font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--s3-ink-muted, #5c5a52); }
.chip { position: relative; display: block; }
.chip input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; }
.chip > span { display: inline-flex; align-items: center; gap: 7px; min-height: 32px; padding: 0 11px; border: 1px solid var(--s3-line-strong, #11110f); border-radius: 999px; font-size: 0.8125rem; transition: background-color var(--s3-duration-fast, 160ms) var(--s3-ease-standard, ease); }
.chip input:checked + span { background: var(--s3-surface, #fbf9f4); font-weight: 500; }
.chip input:checked + span::before { content: '✓'; font-size: 0.7rem; }
.chip input:not(:checked) + span { border-style: dashed; color: var(--s3-ink-muted, #5c5a52); }
.chip input:focus-visible + span { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: 2px; }
.chip input:disabled { cursor: not-allowed; }
.chipN { font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.6875rem; font-variant-numeric: tabular-nums; }
.swatch { display: inline-block; width: 9px; height: 9px; margin-right: 6px; border-radius: 50%; vertical-align: 0; }
.chip .swatch { margin: 0; }
.swatch[data-mark='washed'] { background: var(--de-washed); }
.swatch[data-mark='natural'] { background: var(--de-natural); border-radius: 1px; }
.swatch[data-mark='honey'] { background: var(--de-honey); clip-path: polygon(50% 0, 100% 100%, 0 100%); border-radius: 0; }
.compare { display: flex; flex-wrap: wrap; gap: 8px; align-items: flex-end; }
.selectLabel { display: grid; gap: 6px; }
.selectLabel > span { display: inline-flex; align-items: center; gap: 6px; font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--s3-ink-muted, #5c5a52); }
.selectLabel select { min-height: 32px; padding: 0 28px 0 10px; border: 1px solid var(--s3-line-strong, #11110f); border-radius: 6px; background: var(--s3-surface, #fbf9f4); color: var(--s3-ink, #11110f); font: inherit; font-size: 0.8125rem; }
.selectLabel select:focus-visible { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: 2px; }
.groupKey { width: 10px; height: 10px; }
.groupKey[data-g='a'] { background: var(--s3-ink, #11110f); border-radius: 50%; }
.groupKey[data-g='b'] { box-shadow: inset 0 0 0 2px var(--s3-signal, #bf2f09); }
.btn { display: inline-flex; align-items: center; min-height: 32px; padding: 0 12px; border: 1px solid var(--s3-line-strong, #11110f); border-radius: 999px; background: transparent; color: inherit; font: inherit; font-size: 0.8125rem; font-weight: 500; white-space: nowrap; }
.btn:hover { background: var(--s3-ink, #11110f); color: var(--s3-bg, #f3f0e8); }
.btn:focus-visible, .linkBtn:focus-visible, .crumbBtn:focus-visible, .sortBtn:focus-visible, .pinBtn:focus-visible { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: 2px; }
.toolbar .btn { margin-left: auto; }
.linkBtn { min-height: 24px; padding: 0 2px; border: 0; background: none; color: inherit; font: inherit; font-size: 0.8125rem; text-decoration: underline; text-underline-offset: 3px; }

.crumbs ol { display: flex; flex-wrap: wrap; align-items: center; gap: 4px; margin: 14px 0 0; padding: 0; list-style: none; font-size: 0.875rem; }
.crumbs li + li::before { content: '›'; margin-right: 4px; color: var(--s3-ink-muted, #5c5a52); }
.crumbBtn { min-height: 28px; padding: 0 4px; border: 0; background: none; color: inherit; font: inherit; text-decoration: underline; text-underline-offset: 3px; }
.crumbHere { padding: 0 4px; font-family: var(--s3-font-serif, Georgia, serif); font-size: 1.125rem; font-style: italic; }

/* ── views ────────────────────────────────────────────────────── */
.views { display: grid; gap: 32px; margin-top: 18px; }
@container (min-width: 1100px) { .views { grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr); gap: 40px; } }
.sideViews { display: grid; gap: 32px; align-content: start; min-width: 0; }
.panel { min-width: 0; padding-top: 12px; border-top: 1px solid var(--s3-line-strong, #11110f); }
.panelTitle { margin: 0; font-family: var(--s3-font-serif, Georgia, serif); font-size: 1.5rem; font-weight: 400; line-height: 1.1; letter-spacing: -0.01em; }
.legend { display: flex; flex-wrap: wrap; gap: 4px 16px; margin: 10px 0 0; padding: 0; list-style: none; font-size: 0.75rem; color: var(--s3-ink-muted, #5c5a52); }
.legend li { display: inline-flex; align-items: center; gap: 6px; }
.lgShape { width: 12px; height: 12px; }
.lgShape[data-mark='washed'] { fill: var(--de-washed); }
.lgShape[data-mark='natural'] { fill: var(--de-natural); }
.lgShape[data-mark='honey'] { fill: var(--de-honey); }
.lgA { width: 10px; height: 10px; border-radius: 50%; background: var(--s3-ink, #11110f); }
.lgB { width: 10px; height: 10px; box-shadow: inset 0 0 0 2px var(--s3-signal, #bf2f09); }
.lgCtx { width: 9px; height: 9px; border-radius: 50%; box-shadow: inset 0 0 0 1px var(--s3-ink-muted, #5c5a52); }
.lgTrend { width: 18px; border-top: 1.5px dashed var(--s3-ink, #11110f); }

.scatter { position: relative; height: clamp(300px, 42cqi, 520px); margin-top: 8px; touch-action: pan-y; }
@container (min-width: 1100px) { .scatter { height: clamp(380px, 34cqi, 520px); } }
.svg { display: block; overflow: visible; }
.grid { stroke: var(--s3-line, #11110f24); stroke-width: 1; shape-rendering: crispEdges; }
.base { stroke: var(--s3-line-strong, #11110f); stroke-width: 1; shape-rendering: crispEdges; }
.tick { fill: var(--s3-ink-muted, #5c5a52); font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 10.5px; font-variant-numeric: tabular-nums; }
.ctx { fill: none; stroke: color-mix(in oklab, var(--s3-ink-muted, #5c5a52) 55%, transparent); stroke-width: 1; }
.pt { stroke: var(--s3-bg, #f3f0e8); stroke-width: 0.8; }
.pt[data-mark='washed'] { fill: var(--de-washed); }
.pt[data-mark='natural'] { fill: var(--de-natural); }
.pt[data-mark='honey'] { fill: var(--de-honey); }
.pt[data-mark='a'] { fill: var(--s3-ink, #11110f); }
.pt[data-mark='b'] { fill: var(--s3-bg, #f3f0e8); stroke: var(--s3-signal, #bf2f09); stroke-width: 1.8; }
.trend line { stroke: var(--s3-ink, #11110f); stroke-width: 1.5; stroke-dasharray: 6 4; }
.trend text { fill: var(--s3-ink, #11110f); font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 11px; font-weight: 600; paint-order: stroke; stroke: var(--s3-bg, #f3f0e8); stroke-width: 4px; }
.brushRect { fill: color-mix(in oklab, var(--de-washed) 7%, transparent); stroke: var(--s3-ink, #11110f); stroke-width: 1; stroke-dasharray: 3 3; }
.draftRect { fill: color-mix(in oklab, var(--s3-ink, #11110f) 6%, transparent); stroke: var(--s3-ink, #11110f); stroke-width: 1; }
.pinRing { fill: none; stroke: var(--s3-ink, #11110f); stroke-width: 2; }
.focusRing { fill: none; stroke: var(--s3-focus, #1d4ed8); stroke-width: 2; }
.hit { position: absolute; inset: 0; cursor: crosshair; border-radius: 4px; }
.hit:focus-visible { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: 4px; }
.tip { position: absolute; top: 0; left: 0; width: 0; pointer-events: none; z-index: 2; }
.tip > div { position: absolute; bottom: 12px; display: grid; gap: 2px; width: max-content; max-width: 240px; padding: 7px 10px; border-radius: 4px; background: var(--s3-ink, #11110f); color: var(--s3-bg, #f3f0e8); font-size: 0.75rem; line-height: 1.35; }
.tip > div strong { font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.75rem; }
.tip[data-side='right'] > div { left: 10px; }
.tip[data-side='left'] > div { right: 10px; }
.axisTitle { display: flex; justify-content: space-between; gap: 12px; margin: 2px 0 0; padding-left: 46px; font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.04em; color: var(--s3-ink-muted, #5c5a52); }
.stripLabel { margin: 14px 0 4px; font-size: 0.75rem; color: var(--s3-ink-muted, #5c5a52); }
.stripSvg { position: absolute; inset: 0; display: block; overflow: visible; }
.altBar { fill: color-mix(in oklab, var(--s3-ink, #11110f) 18%, transparent); }

/* brushes (shared by the score histogram and the altitude strip) */
.brush { position: relative; margin-top: 8px; touch-action: pan-y; cursor: crosshair; }
.brush:not([data-active]) .window { border-style: dashed; border-color: var(--s3-line-strong, #11110f); }
.shade { position: absolute; top: 0; bottom: 0; background: color-mix(in oklab, var(--s3-bg, #f3f0e8) 62%, transparent); pointer-events: none; }
.window { position: absolute; top: 0; bottom: 0; border: 1.5px solid var(--s3-ink, #11110f); cursor: grab; }
.window:focus-visible, .handle:focus-visible { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: 2px; }
.handle { position: absolute; top: 0; bottom: 0; width: 26px; transform: translateX(-50%); display: grid; place-items: center; cursor: ew-resize; z-index: 1; }
.handle > span { width: 6px; height: min(26px, 70%); border-radius: 3px; background: var(--s3-ink, #11110f); box-shadow: 0 0 0 2px var(--s3-bg, #f3f0e8); }
.histSvg { position: absolute; inset: 0; display: block; overflow: visible; }
.barAll { fill: none; stroke: var(--s3-ink-muted, #5c5a52); stroke-width: 1; }
.barSel { fill: var(--s3-ink, #11110f); }
.barA { fill: var(--s3-ink, #11110f); }
.stepB { fill: none; stroke: var(--s3-signal, #bf2f09); stroke-width: 2.25; stroke-linejoin: miter; }
.inlineRow { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; margin-top: 10px; }

/* drill-down dot plot */
.dots { margin-top: 12px; }
.dotAxis, .dotBtn { display: grid; grid-template-columns: minmax(0, 10.5rem) minmax(0, 1fr) 3.4rem 1rem; align-items: center; gap: 12px; }
@container (max-width: 520px) { .dotAxis, .dotBtn { grid-template-columns: minmax(0, 7.5rem) minmax(0, 1fr) 3rem 0.75rem; gap: 8px; } }
.dotAxisTrack { position: relative; height: 16px; border-bottom: 1px solid var(--s3-line-strong, #11110f); }
.dotAxisTrack span { position: absolute; top: 0; transform: translateX(-50%); font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 10px; color: var(--s3-ink-muted, #5c5a52); }
.dotList { position: relative; margin: 0; padding: 0; list-style: none; }
.dotRow { position: absolute; inset-inline: 0; top: 0; height: 40px; }
.dotBtn { width: 100%; height: 40px; padding: 0; border: 0; border-bottom: 1px solid var(--s3-line, #11110f24); background: transparent; color: inherit; font: inherit; text-align: left; }
.dotBtn:hover:not(:disabled) { background: var(--s3-surface, #fbf9f4); }
.dotBtn:focus-visible { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: -2px; }
.dotBtn:disabled { cursor: default; }
.dotBtn[aria-pressed='true'] { background: var(--s3-surface-2, #e9e5da); }
.dotName { display: flex; align-items: baseline; gap: 8px; min-width: 0; }
.dotNameText { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 0.8125rem; font-weight: 500; }
.dotN { flex: none; font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.6875rem; color: var(--s3-ink-muted, #5c5a52); }
.dotTrack { position: relative; height: 100%; background: repeating-linear-gradient(to right, var(--s3-line, #11110f24) 0 1px, transparent 1px 20%) 0 0 / 100% 100% no-repeat; }
.whisker { position: absolute; top: 50%; height: 2px; margin-top: -1px; background: var(--s3-ink-muted, #5c5a52); }
.dot { position: absolute; top: 50%; width: 11px; height: 11px; margin: -5.5px 0 0 -5.5px; border-radius: 50%; background: var(--s3-ink, #11110f); box-shadow: 0 0 0 2px var(--s3-bg, #f3f0e8); }
.dot[data-pinned] { background: var(--s3-signal, #bf2f09); }
.dumbbell { position: absolute; top: 50%; height: 2px; margin-top: -1px; background: var(--s3-line-strong, #11110f); }
.dotA { position: absolute; top: 50%; width: 11px; height: 11px; margin: -5.5px 0 0 -5.5px; border-radius: 50%; background: var(--s3-ink, #11110f); }
.dotB { position: absolute; top: 50%; width: 10px; height: 10px; margin: -5px 0 0 -5px; background: var(--s3-bg, #f3f0e8); box-shadow: inset 0 0 0 2px var(--s3-signal, #bf2f09); }
.dotVal { font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.8125rem; font-weight: 600; text-align: right; font-variant-numeric: tabular-nums; }
.chev { font-size: 1rem; color: var(--s3-ink-muted, #5c5a52); }

/* ── readout ──────────────────────────────────────────────────── */
.readout { display: grid; gap: 28px; margin-top: 36px; padding-top: 14px; border-top: 1px solid var(--s3-line-strong, #11110f); }
@container (min-width: 1000px) { .readout { grid-template-columns: minmax(0, 1.6fr) minmax(0, 1fr); gap: 48px; } }
.summaryBlock, .pinBlock { min-width: 0; }
.summary { max-width: 70ch; margin: 8px 0 0; font-family: var(--s3-font-serif, Georgia, serif); font-size: clamp(1.15rem, 2.2cqi, 1.45rem); line-height: 1.35; text-wrap: pretty; font-variant-numeric: lining-nums; }
.cmpTable { width: 100%; max-width: 560px; margin-top: 14px; border-collapse: collapse; font-size: 0.8125rem; font-variant-numeric: tabular-nums; }
.cmpTable th, .cmpTable td { height: 32px; padding: 0 8px; border-bottom: 1px solid var(--s3-line, #11110f24); text-align: left; font-weight: 400; }
.cmpTable thead th { font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.04em; color: var(--s3-ink-muted, #5c5a52); border-bottom-color: var(--s3-line-strong, #11110f); }
.pinId { margin: 8px 0 0; font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 1.25rem; font-weight: 600; }
.pinFacts { display: grid; grid-template-columns: repeat(auto-fill, minmax(8.5rem, 1fr)); gap: 0 16px; margin: 8px 0 0; }
.pinFacts div { padding: 6px 0; border-bottom: 1px solid var(--s3-line, #11110f24); }
.pinFacts dt { font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.625rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--s3-ink-muted, #5c5a52); }
.pinFacts dd { margin: 0; font-size: 0.8125rem; font-variant-numeric: tabular-nums; }

/* ── table ────────────────────────────────────────────────────── */
.lots { margin-top: 40px; }
.lotsHead { padding-top: 12px; border-top: 1px solid var(--s3-line-strong, #11110f); }
.tableBox { display: block; margin-top: 10px; overflow: auto; max-height: 460px; border-top: 1px solid var(--s3-line, #11110f24); overscroll-behavior: contain; }
.tableBox[hidden] { display: none; }
.tableBox:focus-visible { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: 2px; }
.table { width: 100%; border-collapse: separate; border-spacing: 0; font-size: 0.8125rem; font-variant-numeric: tabular-nums lining-nums; }
.table th, .table td { height: 34px; padding: 0 10px; border-bottom: 1px solid var(--s3-line, #11110f24); text-align: left; font-weight: 400; white-space: nowrap; }
.table thead th { position: sticky; top: 0; z-index: 1; background: var(--s3-bg, #f3f0e8); border-bottom-color: var(--s3-line-strong, #11110f); font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.04em; color: var(--s3-ink-muted, #5c5a52); }
.num { text-align: right !important; font-family: var(--s3-font-mono, ui-monospace, monospace); }
.caption { caption-side: bottom; padding: 8px 0; text-align: left; font-size: 0.75rem; color: var(--s3-ink-muted, #5c5a52); }
.lotTable { min-width: 760px; }
.lotTable tbody tr[data-pinned] > * { background: var(--s3-surface-2, #e9e5da); }
.sortBtn { display: inline-flex; align-items: center; min-height: 28px; padding: 0; border: 0; background: none; color: inherit; font: inherit; letter-spacing: inherit; }
.num .sortBtn { justify-content: flex-end; width: 100%; }
.pinBtn { min-height: 28px; padding: 0 6px; margin-left: -6px; border: 0; border-radius: 4px; background: none; color: inherit; font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.78rem; font-weight: 600; text-decoration: underline; text-decoration-color: var(--s3-line-strong, #11110f); text-underline-offset: 3px; font-variant-numeric: slashed-zero; }
.pinBtn[aria-pressed='true'] { background: var(--s3-ink, #11110f); color: var(--s3-bg, #f3f0e8); text-decoration: none; }
.empty { padding: 14px 0; color: var(--s3-ink-muted, #5c5a52); }

.foot { max-width: 92ch; margin-top: 36px; padding-top: 12px; border-top: 1px solid var(--s3-line, #11110f24); font-size: 0.75rem; line-height: 1.55; color: var(--s3-ink-muted, #5c5a52); }
.foot p { margin: 0; }
.foot strong { color: var(--s3-ink, #11110f); font-weight: 600; }
